	ARTERIAL_SPRAY(26, "Arterial Spray", 10, Boss.ZEBAK),
	BLOOD_THINNERS(27, "Blood Thinners", 5, Boss.ZEBAK),
	UPSET_STOMACH(28, "Upset Stomach", 15, Boss.ZEBAK),
	DOUBLE_TROUBLE(29, "Double Trouble", 20, Boss.AKKHA),
	KEEP_BACK(30, "Keep Back", 10, Boss.AKKHA),
	STAY_VIGILANT(31, "Stay Vigilant", 15, Boss.AKKHA),
	FEELING_SPECIAL(32, "Feeling Special?", 20, Boss.AKKHA),
	MIND_THE_GAP(33, "Mind the Gap!", 10, Boss.BABA),
	GOTTA_HAVE_FAITH(34, "Gotta Have Faith", 10, Boss.BABA),
	JUNGLE_JAPES(35, "Jungle Japes", 5, Boss.BABA),
	SHAKING_THINGS_UP(36, "Shaking Things Up", 10, Boss.BABA),
	BOULDERDASH(37, "Boulderdash", 10, Boss.BABA),
	ANCIENT_HASTE(38, "Ancient Haste", 10, Boss.WARDENS),
	ACCELERATION(39, "Acceleration", 10, Boss.WARDENS),
	PENETRATION(40, "Penetration", 10, Boss.WARDENS),
	OVERCLOCKED(41, "Overclocked", 10, Boss.WARDENS),
	OVERCLOCKED_2(42, "Overclocked 2", 10, Boss.WARDENS),
	INSANITY(43, "Insanity", 50, Boss.WARDENS);

	public final int uiIndex;
	public final String displayName;
	public final int raidPoints;
	public final Boss boss;
	private final String matchName;

	Invocation(int uiIndex, String displayName, int raidPoints, Boss boss)
	{
		this.uiIndex = uiIndex;
		this.displayName = displayName;
		this.raidPoints = raidPoints;
		this.boss = boss;
		this.matchName = normalize(displayName);
	}

	public boolean isPathInvocation()
	{
		return uiIndex >= 11 && uiIndex <= 14;
	}

	public static Invocation fromName(String name)
	{
		String normalized = normalize(name);
		for (Invocation invocation : values())
		{
			if (invocation.matchName.equals(normalized))
			{
				return invocation;
			}
		}
		return null;
	}

	private static String normalize(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "")
			.replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class InvocationReader
{
	// Observed by the ToA Invocation Display author for non-leaders. See RESEARCH.md.
	private static final int ACTIVE_LABEL_COLOR = 0xD39034;
	private static final Pattern SINGLE_NUMBER = Pattern.compile("^(?:Raid [Ll]evel:?\\s*)?(\\d+)$");

	private InvocationReader() {}

	public static InvocationSelection read(Client client)
	{
		Widget parent = client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT);
		if (parent == null || parent.isHidden() || parent.getChildren() == null)
		{
			return null;
		}
		Widget[] children = parent.getChildren();
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		boolean usedColor = false;
		for (int i = 2; i < children.length; i++)
		{
			Widget label = children[i];
			Invocation invocation = label == null ? null : Invocation.fromName(label.getText());
			if (invocation == null)
			{
				continue;
			}
			if (states.containsKey(invocation))
			{
				return null; // Ambiguous or partially rebuilt layout.
			}
			Widget background = children[i - 2];
			Object[] args = background == null ? null : background.getOnOpListener();
			Boolean active = null;
			if (args != null && args.length >= 4)
			{
				if (Integer.valueOf(1).equals(args[3])) active = true;
				else if (Integer.valueOf(0).equals(args[3])) active = false;
			}
			if (active == null)
			{
				usedColor = true;
				active = label.getTextColor() == ACTIVE_LABEL_COLOR;
			}
			states.put(invocation, active);
		}
		Integer points = number(client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL));
		if (points == null)
		{
			points = number(client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL_INVOCATIONS));
		}
		// Color reads need a matching score so a default-grey loading frame cannot erase selections.
		// A real zero-invocation raid with a displayed score of zero is valid.
		if (usedColor && points == null)
		{
			return null;
		}
		return InvocationSelection.validate(states, points);
	}

	public static Integer number(Widget widget)
	{
		if (widget == null || widget.isHidden()) return null;
		String text = widget.getText();
		if (text == null) return null;
		Matcher matcher = SINGLE_NUMBER.matcher(text.replaceAll("<[^>]*>", "").trim());
		if (!matcher.matches()) return null;
		try { return Integer.valueOf(matcher.group(1)); }
		catch (NumberFormatException ex) { return null; }
	}
}

package com.cornwall92.toapathwatch;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** A complete observed selection. null at the reader boundary means unknown, not empty. */
public final class InvocationSelection
{
	public final Set<Invocation> active;
	public final int raidPoints;

	private InvocationSelection(Set<Invocation> active, int raidPoints)
	{
		this.active = Collections.unmodifiableSet(active);
		this.raidPoints = raidPoints;
	}

	public static InvocationSelection validate(Map<Invocation, Boolean> states, Integer displayedPoints)
	{
		if (states.size() != Invocation.values().length || states.containsValue(null))
		{
			return null;
		}
		EnumSet<Invocation> active = EnumSet.noneOf(Invocation.class);
		int sum = 0;
		for (Invocation inv : Invocation.values())
		{
			if (Boolean.TRUE.equals(states.get(inv)))
			{
				active.add(inv);
				sum += inv.raidPoints;
			}
		}
		if (displayedPoints != null && displayedPoints != sum)
		{
			return null;
		}
		return new InvocationSelection(active, sum);
	}
}

package com.cornwall92.toapathwatch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Static reference text, not an attack tracker. Sources and limits: RESEARCH.md. */
public final class PathMechanics
{
	private PathMechanics() {}

	public static int tier(int level)
	{
		checkLevel(level);
		return Math.min(level / 2, 2);
	}

	public static int statBonusPercent(int level)
	{
		checkLevel(level);
		return level == 0 ? 0 : 3 + 5 * level;
	}

	private static void checkLevel(int level)
	{
		if (level < 0 || level > 6)
		{
			throw new IllegalArgumentException("Path level must be 0-6");
		}
	}

	public static List<String> describe(Boss boss, int level)
	{
		if (boss == Boss.WARDENS)
		{
			return Collections.singletonList("No separate Warden path level.");
		}
		int tier = tier(level);
		List<String> lines = new ArrayList<>();
		if (tier == 0)
		{
			lines.add("No level-2/4 mechanic upgrades.");
			return Collections.unmodifiableList(lines);
		}
		switch (boss)
		{
			case AKKHA:
				lines.add("Memory Blast: " + (4 + tier) + " steps (base 4).");
				lines.add("Final-phase orbs hit harder; cap 25.");
				break;
			case BABA:
				lines.add(tier == 1 ? "Rockfall drops faster." : "Rockfall drops even faster.");
				lines.add(tier == 1 ? "Sarcophagus blasts cover more tiles." : "Sarcophagus blast area grows again.");
				lines.add("Rolling boulder base HP: " + (tier == 1 ? "27" : "31") + " (before raid scaling).");
				break;
			case KEPHRI:
				lines.add(tier == 1 ? "Faster fireball attacks." : "Fireball attacks speed up again.");
				lines.add(tier == 1 ? "Healing swarms can spawn in threes." : "Triple healing swarms occur more often.");
				break;
			case ZEBAK:
				lines.add(tier == 1 ? "Faster attacks, including enrage." : "Attacks: 5 ticks; enrage: 2 ticks.");
				lines.add("Wave gap: " + (3 - tier) + " tile" + (tier == 1 ? "s." : "."));
				break;
			default:
				throw new IllegalArgumentException("No boss supplied");
		}
		return Collections.unmodifiableList(lines);
	}
}

package com.cornwall92.toapathwatch;

/**
 * Client-thread state for a lobby capture and its frozen raid selection.
 * Unknown geography is a temporary absence of evidence, not a confirmed exit.
 */
public final class RaidSelectionTracker
{
	private static final int LOBBY_REGION = 13454;
	private static final int NEXUS_REGION = 14160;
	private static final int UNKNOWN_GRACE_TICKS = 3;
	private static final int ENTRY_SCORE_ATTEMPTS = 5;

	private boolean inRaid;
	private InvocationSelection lobbyCandidate;
	private InvocationSelection entryCandidate;
	private InvocationSelection selection;
	private int unknownTicks;
	private int scoreAttemptsRemaining;

	/** Call only with a selection read from the current party's lobby interface. */
	public void capture(InvocationSelection captured)
	{
		if (!inRaid)
		{
			lobbyCandidate = captured;
		}
	}

	public void invalidateLobby()
	{
		lobbyCandidate = null;
	}

	/**
	 * Called once per game tick. A region of -1 means the local position is unknown.
	 * There are five score observations, including the first entry tick. Subsequent
	 * observations are permitted only in the nexus; entering a path closes the window.
	 */
	public void update(int region, int raidPoints)
	{
		if (region == -1)
		{
			if (++unknownTicks > UNKNOWN_GRACE_TICKS)
			{
				reset();
			}
			return;
		}
		unknownTicks = 0;

		if (!Boss.isRaidRegion(region))
		{
			if (inRaid || region != LOBBY_REGION)
			{
				reset();
			}
			return;
		}

		boolean entering = !inRaid;
		if (entering)
		{
			inRaid = true;
			entryCandidate = lobbyCandidate;
			lobbyCandidate = null;
			selection = null;
			scoreAttemptsRemaining = ENTRY_SCORE_ATTEMPTS;
		}

		if (entryCandidate == null)
		{
			return;
		}
		if (!entering && region != NEXUS_REGION)
		{
			clearEntryCandidate();
			return;
		}

		if (entryCandidate.raidPoints == raidPoints)
		{
			selection = entryCandidate;
			clearEntryCandidate();
		}
		else if (--scoreAttemptsRemaining == 0)
		{
			clearEntryCandidate();
		}
	}

	private void clearEntryCandidate()
	{
		entryCandidate = null;
		scoreAttemptsRemaining = 0;
	}

	public InvocationSelection getSelection()
	{
		return selection;
	}

	public boolean isInRaid()
	{
		return inRaid;
	}

	public void reset()
	{
		inRaid = false;
		lobbyCandidate = null;
		entryCandidate = null;
		selection = null;
		unknownTicks = 0;
		scoreAttemptsRemaining = 0;
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Constants.SCENE_SIZE;

/** Resolves a template region without treating an unloaded instance chunk as an exit. */
public final class RegionResolver
{
	private RegionResolver() {}

	/** Must be called on the client thread. -1 means the location is not yet known. */
	public static int region(Client client)
	{
		Player player = client.getLocalPlayer();
		if (player == null) return -1;
		LocalPoint local = player.getLocalLocation();
		if (local == null) return -1;
		WorldView worldView = client.getWorldView(local.getWorldView());
		if (worldView == null) return -1;

		if (!worldView.isInstance())
		{
			return WorldPoint.fromLocal(worldView, local.getX(), local.getY(), worldView.getPlane()).getRegionID();
		}

		int sceneX = local.getSceneX();
		int sceneY = local.getSceneY();
		if (sceneX < 0 || sceneY < 0 || sceneX >= SCENE_SIZE || sceneY >= SCENE_SIZE) return -1;
		int plane = worldView.getPlane();
		int chunkX = sceneX / CHUNK_SIZE;
		int chunkY = sceneY / CHUNK_SIZE;
		int[][][] chunks = worldView.getInstanceTemplateChunks();
		if (chunks == null || plane < 0 || plane >= chunks.length || chunks[plane] == null
			|| chunkX >= chunks[plane].length || chunks[plane][chunkX] == null
			|| chunkY >= chunks[plane][chunkX].length || chunks[plane][chunkX][chunkY] == -1)
		{
			return -1;
		}
		// RuneLite's conversion assumes the chunk is loaded: -1 otherwise decodes to
		// a synthetic region rather than an unknown result, prematurely clearing a raid.
		return WorldPoint.fromLocalInstance(client, local).getRegionID();
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
