@ConfigGroup(ToaPathwatchConfig.GROUP)
public interface ToaPathwatchConfig extends Config
{
	String GROUP = "toa-path-info";

	@ConfigItem(keyName = "showGlobals", name = "Other raid invocations", description = "Include active general invocations as well as path and boss selections", position = 0)
	default boolean showGlobals() { return false; }

	@ConfigItem(keyName = "showPuzzles", name = "Show in puzzle rooms", description = "Show the path reference in its puzzle room too", position = 1)
	default boolean showPuzzles() { return false; }

	@ConfigItem(keyName = "showScaling", name = "Show path stat increase", description = "Show additional HP/damage scaling from path level only", position = 2)
	default boolean showScaling() { return true; }

	@ConfigItem(keyName = "showPoints", name = "Invocation raid points", description = "Display each invocation's contribution to the raid level", position = 3)
	default boolean showPoints() { return false; }

	@Range(min = 180, max = 450)
	@ConfigItem(keyName = "width", name = "Panel width", description = "Width of the movable reference panel", position = 4)
	default int width() { return 260; }
}

package com.cornwall92.toapathwatch;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class ToaPathwatchOverlay extends OverlayPanel
{
	private static final Color GOLD = new Color(255, 195, 85);
	private static final Color GREEN = new Color(130, 220, 155);
	private final ToaPathwatchPlugin plugin;
	private final ToaPathwatchConfig config;

	@Inject
	ToaPathwatchOverlay(ToaPathwatchPlugin plugin, ToaPathwatchConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setResizable(false);
	}

	private void line(String text, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(text).leftColor(color).build());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Boss boss = plugin.getBoss();
		if (boss == null) return null;
		int level = plugin.getPathLevel();
		panelComponent.setPreferredSize(new Dimension(config.width(), 0));
		String title = boss.displayName + (boss == Boss.WARDENS ? "" : " - Path " + (level < 0 ? "?" : level));
		panelComponent.getChildren().add(TitleComponent.builder().text(title).color(GOLD).build());
		InvocationSelection selection = plugin.getSelection();
		line("Active invocations", GOLD);
		if (selection == null)
		{
			line("Not captured. Open your party's invocation tab before entering the raid.", Color.LIGHT_GRAY);
		}
		else
		{
			boolean any = false;
			for (Invocation invocation : Invocation.values())
			{
				if (selection.active.contains(invocation) && (invocation.boss == boss || invocation.isPathInvocation()
					|| (config.showGlobals() && invocation.boss == null)))
				{
					line(invocation.displayName + (config.showPoints() ? " (+" + invocation.raidPoints + ")" : ""), GREEN);
					any = true;
				}
			}
			if (!any) line("None relevant enabled.", Color.LIGHT_GRAY);
		}
		line("Path effects", GOLD);
		if (boss == Boss.WARDENS)
		{
			line("No separate Warden path level.", Color.LIGHT_GRAY);
		}
		else if (level < 0)
		{
			line("Waiting for path level.", Color.LIGHT_GRAY);
		}
		else
		{
			if (config.showScaling()) line("Path HP / damage: +" + PathMechanics.statBonusPercent(level) + "%", Color.WHITE);
			for (String effect : PathMechanics.describe(boss, level)) line(effect, Color.WHITE);
		}
		return super.render(graphics);
	}
}

package com.cornwall92.toapathwatch;

import com.google.inject.Provides;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "ToA Pathwatch", description = "Current invocations and path-level reference", tags = {"toa", "invocations", "path", "reference"})
public class ToaPathwatchPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private ToaPathwatchOverlay overlay;
	@Inject private ToaPathwatchConfig config;

	private volatile boolean enabled;
	private final AtomicInteger generation = new AtomicInteger();
	private boolean captureQueued;
	private final RaidSelectionTracker selections = new RaidSelectionTracker();
	private Boss boss;
	private int pathLevel = -1;

	@Override
	protected void startUp()
	{
		enabled = true;
		int startupGeneration = generation.incrementAndGet();
		overlayManager.add(overlay);
		clientThread.invokeLater(() ->
		{
			if (enabled && generation.get() == startupGeneration)
			{
				clearState();
				refresh();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		enabled = false;
		int shutdownGeneration = generation.incrementAndGet();
		overlayManager.remove(overlay);
		clientThread.invokeLater(() ->
		{
			if (!enabled && generation.get() == shutdownGeneration) clearState();
		});
	}

	/** Called only on the client thread, including lifecycle cleanup. */
	private void clearState()
	{
		captureQueued = false;
		selections.reset();
		boss = null;
		pathLevel = -1;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			generation.incrementAndGet();
			clearState();
		}
		else if (event.getGameState() != GameState.LOGGED_IN)
		{
			boss = null;
			pathLevel = -1;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) { refresh(); }

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// Party build, invocation rebuild, and reward-tab toggle. Not RuneLite API constants.
		int id = event.getScriptId();
		if (id == 6617 || id == 6729 || id == 6732) queueCapture();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!selections.isInRaid() && event.getVarpId() == VarPlayerID.TOA_MYCONTROLLER)
		{
			selections.invalidateLobby();
			queueCapture();
		}
	}

	private int region()
	{
		return RegionResolver.region(client);
	}

	private void captureInvocations()
	{
		if (!enabled || client.getGameState() != GameState.LOGGED_IN || region() != 13454) return;
		InvocationSelection selection = InvocationReader.read(client);
		if (selection != null) selections.capture(selection);
		else
		{
			// An open but unreadable grid may represent changed selections. Discard stale data.
			var widget = client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT);
			if (widget != null && !widget.isHidden()) selections.invalidateLobby();
		}
	}

	private void queueCapture()
	{
		if (!enabled || captureQueued) return;
		captureQueued = true;
		int queuedGeneration = generation.get();
		// The invocation interface can still be rebuilding inside its script callback.
		// Re-read the complete selection after the client finishes this update, including presets.
		clientThread.invokeLater(() ->
		{
			if (!enabled || generation.get() != queuedGeneration) return;
			captureQueued = false;
			captureInvocations();
		});
	}

	private void refresh()
	{
		if (!enabled || client.getGameState() != GameState.LOGGED_IN) return;
		int region = region();
		// Raid points validate an observed selection; they cannot identify invocations alone.
		selections.update(region, client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL));
		if (region == 13454) queueCapture();
		boss = Boss.forRegion(region, config.showPuzzles());
		pathLevel = -1;
		if (boss != null && boss != Boss.WARDENS)
		{
			Integer hud = InvocationReader.number(client.getWidget(InterfaceID.ToaHud.PATHS_LEVEL));
			// Use the displayed level until the raw varbit encoding is verified in-game.
			if (hud != null && hud >= 0 && hud <= 6) pathLevel = hud;
		}
	}

	Boss getBoss() { return boss; }
	int getPathLevel() { return pathLevel; }
	InvocationSelection getSelection() { return selections.getSelection(); }

	@Provides
	ToaPathwatchConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(ToaPathwatchConfig.class);
	}
}

package com.cornwall92.toapathwatch;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/** Exercises the actual widget reader with synthetic interface contents, not game input. */
public class InvocationReaderTest
{
	private static final int ACTIVE = 0xD39034;
	private static final int INACTIVE = 0x808080;

	private static final class Grid
	{
		private final Client client = mock(Client.class);
		private final Widget parent = mock(Widget.class);
		private final Widget score = mock(Widget.class);
		private final boolean leader;
		private Widget[] children;

		private Grid(boolean leader, Invocation... active)
		{
			this.leader = leader;
			when(client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT)).thenReturn(parent);
			when(client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL)).thenReturn(score);
			populate(active);
		}

		private void populate(Invocation... active)
		{
			Set<Invocation> enabled = EnumSet.noneOf(Invocation.class);
			enabled.addAll(Arrays.asList(active));
			children = new Widget[Invocation.values().length * 3];
			int points = 0;
			for (Invocation invocation : Invocation.values())
			{
				boolean selected = enabled.contains(invocation);
				int index = invocation.uiIndex * 3;
				Widget background = mock(Widget.class);
				Widget label = mock(Widget.class);
				children[index] = background;
				children[index + 1] = mock(Widget.class);
				children[index + 2] = label;
				when(label.getText()).thenReturn(invocation.displayName);
				when(label.getTextColor()).thenReturn(selected ? ACTIVE : INACTIVE);
				if (leader)
				{
					when(background.getOnOpListener()).thenReturn(new Object[]{6729, 0, 0, selected ? 1 : 0});
				}
				if (selected) points += invocation.raidPoints;
			}
			when(parent.getChildren()).thenReturn(children);
			when(score.getText()).thenReturn("Raid Level: " + points);
		}
	}

	@Test public void leaderButtonStateOverridesContradictoryLabelColor()
	{
		Grid grid = new Grid(true, Invocation.WALK_THE_PATH, Invocation.FEELING_SPECIAL);
		for (Invocation invocation : Invocation.values())
		{
			boolean selected = invocation == Invocation.WALK_THE_PATH || invocation == Invocation.FEELING_SPECIAL;
			when(grid.children[invocation.uiIndex * 3 + 2].getTextColor()).thenReturn(selected ? INACTIVE : ACTIVE);
		}
		InvocationSelection result = InvocationReader.read(grid.client);
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.WALK_THE_PATH, Invocation.FEELING_SPECIAL), result.active);
	}

	@Test public void nonleaderColorReadRequiresAndMatchesFullPartyScore()
	{
		Grid grid = new Grid(false, Invocation.PATHFINDER, Invocation.MEDIC, Invocation.NEED_LESS_HELP);
		InvocationSelection result = InvocationReader.read(grid.client);
		assertNotNull(result);
		assertEquals(EnumSet.of(Invocation.PATHFINDER, Invocation.MEDIC, Invocation.NEED_LESS_HELP), result.active);
		assertEquals(80, result.raidPoints);
	}

	@Test public void completeZeroSelectionIsKnownForNonleader()
	{
		Grid grid = new Grid(false);
		InvocationSelection result = InvocationReader.read(grid.client);
		assertNotNull(result);
		assertTrue(result.active.isEmpty());
		assertEquals(0, result.raidPoints);
	}

	@Test public void missingLabelRejectsPartialGrid()
	{
		Grid grid = new Grid(true, Invocation.WALK_THE_PATH);
		grid.children[Invocation.INSANITY.uiIndex * 3 + 2] = null;
		assertNull(InvocationReader.read(grid.client));
	}

	@Test public void duplicateLabelRejectsAmbiguousGrid()
	{
		Grid grid = new Grid(true, Invocation.WALK_THE_PATH);
		Widget[] duplicated = Arrays.copyOf(grid.children, grid.children.length + 3);
		duplicated[duplicated.length - 1] = grid.children[Invocation.WALK_THE_PATH.uiIndex * 3 + 2];
		when(grid.parent.getChildren()).thenReturn(duplicated);
		assertNull(InvocationReader.read(grid.client));
	}

	@Test public void colorCaptureWithoutScoreIsUnknown()
	{
		Grid grid = new Grid(false, Invocation.WALK_THE_PATH);
		when(grid.client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL)).thenReturn(null);
		assertNull(InvocationReader.read(grid.client));
	}

	@Test public void alternateScoreWidgetCanValidateColorCapture()
	{
		Grid grid = new Grid(false, Invocation.WALK_THE_PATH);
		when(grid.client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL)).thenReturn(null);
		when(grid.client.getWidget(InterfaceID.ToaPartydetails.RAID_LEVEL_INVOCATIONS)).thenReturn(grid.score);
		assertNotNull(InvocationReader.read(grid.client));
	}

	@Test public void mismatchingScoreRejectsBothLeaderAndNonleaderCapture()
	{
		for (boolean leader : new boolean[]{true, false})
		{
			Grid grid = new Grid(leader, Invocation.WALK_THE_PATH);
			when(grid.score.getText()).thenReturn("300");
			assertNull(InvocationReader.read(grid.client));
		}
	}

	@Test public void presetReplacementRemovesPreviouslyEnabledInvocations()
	{
		Grid grid = new Grid(true, Invocation.WALK_THE_PATH, Invocation.PATHFINDER);
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection first = InvocationReader.read(grid.client);
		tracker.capture(first);
		grid.populate(Invocation.PATHMASTER, Invocation.MIND_THE_GAP);
		InvocationSelection second = InvocationReader.read(grid.client);
		assertNotNull(second);
		tracker.capture(second);
		tracker.update(14160, 60);
		assertEquals(EnumSet.of(Invocation.PATHMASTER, Invocation.MIND_THE_GAP), tracker.getSelection().active);
		assertEquals(EnumSet.of(Invocation.WALK_THE_PATH, Invocation.PATHFINDER), first.active);
	}

	@Test public void unavailableOrHiddenGridIsUnknown()
	{
		Grid grid = new Grid(true, Invocation.WALK_THE_PATH);
		when(grid.parent.isHidden()).thenReturn(true);
		assertNull(InvocationReader.read(grid.client));
		when(grid.parent.isHidden()).thenReturn(false);
		when(grid.parent.getChildren()).thenReturn(null);
		assertNull(InvocationReader.read(grid.client));
		when(grid.client.getWidget(InterfaceID.ToaPartydetails.INVOCATIONS_CONTENT)).thenReturn(null);
		assertNull(InvocationReader.read(grid.client));
	}

	@Test public void numericReaderAcceptsHudAndFormattedPartyScore()
	{
		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn("4");
		assertEquals(Integer.valueOf(4), InvocationReader.number(widget));
		when(widget.getText()).thenReturn(" <col=ff981f>Raid Level: 300</col> ");
		assertEquals(Integer.valueOf(300), InvocationReader.number(widget));
		when(widget.getText()).thenReturn("Raid level: 150");
		assertEquals(Integer.valueOf(150), InvocationReader.number(widget));
	}

	@Test public void numericReaderRejectsHiddenMissingMalformedAndOverflowValues()
	{
		Widget widget = mock(Widget.class);
		when(widget.getText()).thenReturn("4");
		when(widget.isHidden()).thenReturn(true);
		assertNull(InvocationReader.number(widget));
		when(widget.isHidden()).thenReturn(false);
		for (String value : new String[]{null, "", "4 / 6", "not a level", "-1", "9999999999999999999"})
		{
			when(widget.getText()).thenReturn(value);
			assertNull(InvocationReader.number(widget));
		}
		assertNull(InvocationReader.number(null));
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class RaidSelectionTrackerTest
{
	private static final int LOBBY = 13454;
	private static final int NEXUS = 14160;
	private static final int AKKHA = 14676;
	private static final int OUTSIDE = 12850;

	private InvocationSelection selection(Invocation... active)
	{
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		for (Invocation invocation : Invocation.values()) states.put(invocation, false);
		for (Invocation invocation : active) states.put(invocation, true);
		return InvocationSelection.validate(states, null);
	}

	@Test public void repeatedLobbyTicksPreserveFreshCapture()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		tracker.update(LOBBY, 0);
		tracker.update(LOBBY, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void delayedRaidLevelCanValidateInNexus()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.PATHFINDER);
		tracker.capture(captured);
		tracker.update(NEXUS, 0);
		assertTrue(tracker.isInRaid());
		assertNull(tracker.getSelection());
		tracker.update(NEXUS, 40);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void entryValidationExpiresAfterFiveObservations()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		for (int i = 0; i < 5; i++) tracker.update(NEXUS, 0);
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void entryValidationStillWorksOnFifthObservation()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		for (int i = 0; i < 4; i++) tracker.update(NEXUS, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void leavingNexusClosesPendingValidation()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 0);
		tracker.update(AKKHA, 50);
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void temporaryUnknownRegionDoesNotEraseRaidCapture()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.WALK_THE_PATH);
		tracker.capture(captured);
		tracker.update(NEXUS, 50);
		for (int i = 0; i < 3; i++) tracker.update(-1, 0);
		assertTrue(tracker.isInRaid());
		tracker.update(AKKHA, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void persistentUnknownRegionEventuallyClearsRaid()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 50);
		for (int i = 0; i < 4; i++) tracker.update(-1, 0);
		assertFalse(tracker.isInRaid());
		assertNull(tracker.getSelection());
		tracker.update(AKKHA, 50);
		assertNull(tracker.getSelection());
	}

	@Test public void confirmedExitClearsImmediatelyAndCannotReusePriorCapture()
	{
		for (int destination : new int[]{LOBBY, OUTSIDE})
		{
			RaidSelectionTracker tracker = new RaidSelectionTracker();
			tracker.capture(selection(Invocation.WALK_THE_PATH));
			tracker.update(NEXUS, 50);
			tracker.update(destination, 50);
			assertFalse(tracker.isInRaid());
			assertNull(tracker.getSelection());
			tracker.update(NEXUS, 50);
			assertNull(tracker.getSelection());
		}
	}

	@Test public void frozenCaptureSurvivesLaterScoreChangesAndCaptureAttempts()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection captured = selection(Invocation.RUN_FOR_IT);
		tracker.capture(captured);
		tracker.update(NEXUS, 20);
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.invalidateLobby();
		tracker.update(AKKHA, 0);
		tracker.update(NEXUS, 50);
		assertSame(captured, tracker.getSelection());
	}

	@Test public void newPresetReplacesPreviousLobbySelection()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.RUN_FOR_IT));
		InvocationSelection replacement = selection(Invocation.WALK_THE_PATH);
		tracker.capture(replacement);
		tracker.update(NEXUS, 50);
		assertSame(replacement, tracker.getSelection());
	}

	@Test public void invalidatedGridDoesNotReuseEarlierPreset()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.RUN_FOR_IT));
		tracker.capture(null);
		tracker.update(NEXUS, 20);
		assertNull(tracker.getSelection());
	}

	@Test public void midRaidEnablingDoesNotInventSelection()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.update(AKKHA, 300);
		assertTrue(tracker.isInRaid());
		assertNull(tracker.getSelection());
	}

	@Test public void zeroInvocationRaidIsKnownRatherThanMissing()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		InvocationSelection empty = selection();
		tracker.capture(empty);
		tracker.update(NEXUS, 0);
		assertSame(empty, tracker.getSelection());
		assertTrue(tracker.getSelection().active.isEmpty());
	}

	@Test public void resetClearsFrozenAndPendingData()
	{
		RaidSelectionTracker tracker = new RaidSelectionTracker();
		tracker.capture(selection(Invocation.WALK_THE_PATH));
		tracker.update(NEXUS, 0);
		tracker.reset();
		tracker.update(NEXUS, 50);
		assertNull(tracker.getSelection());
		tracker.reset();
		assertFalse(tracker.isInRaid());
	}
}

package com.cornwall92.toapathwatch;

import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReferenceTest
{
	private Map<Invocation, Boolean> blank()
	{
		Map<Invocation, Boolean> states = new EnumMap<>(Invocation.class);
		for (Invocation inv : Invocation.values()) states.put(inv, false);
		return states;
	}

	@Test public void completeZeroRaidIsKnownEmpty()
	{
		InvocationSelection selection = InvocationSelection.validate(blank(), 0);
		assertNotNull(selection);
		assertTrue(selection.active.isEmpty());
	}

	@Test public void incompleteReadIsUnknown()
	{
		Map<Invocation, Boolean> states = blank();
		states.remove(Invocation.INSANITY);
		assertNull(InvocationSelection.validate(states, 0));
	}

	@Test public void greyLoadingFrameCannotOverwriteNonzeroRaid()
	{
		assertNull(InvocationSelection.validate(blank(), 300));
	}

	@Test public void allInvocationsContributeToScoreIncludingHiddenGlobals()
	{
		Map<Invocation, Boolean> states = blank();
		states.put(Invocation.PATHFINDER, true);
		states.put(Invocation.WALK_THE_PATH, true);
		states.put(Invocation.NEED_LESS_HELP, true);
		InvocationSelection selection = InvocationSelection.validate(states, 115);
		assertNotNull(selection);
		assertEquals(3, selection.active.size());
		assertNull(InvocationSelection.validate(states, 110));
	}

	@Test public void unknownStateIsNotInactive()
	{
		Map<Invocation, Boolean> states = blank();
		states.put(Invocation.KEEP_BACK, null);
		assertNull(InvocationSelection.validate(states, 0));
	}

	@Test public void namesKeepPunctuationAndIgnoreGameColorTags()
	{
		assertSame(Invocation.FEELING_SPECIAL, Invocation.fromName("<col=d39034>Feeling Special?</col>"));
		assertSame(Invocation.MEDIC, Invocation.fromName("Medic!"));
		assertSame(Invocation.MIND_THE_GAP, Invocation.fromName("Mind the Gap!"));
		assertNull(Invocation.fromName("New unrecognised invocation"));
	}

	@Test public void catalogHasAll44UniquePositions()
	{
		assertEquals(44, Invocation.values().length);
		Set<Integer> positions = new HashSet<>();
		for (Invocation inv : Invocation.values())
		{
			assertTrue(positions.add(inv.uiIndex));
			assertSame(inv, Invocation.fromName(inv.displayName));
		}
		for (int i = 0; i < 44; i++) assertTrue(positions.contains(i));
	}

	@Test public void mechanicsChangeOnlyAtTwoAndFour()
	{
		assertEquals(0, PathMechanics.tier(1));
		assertEquals(1, PathMechanics.tier(2));
		assertEquals(1, PathMechanics.tier(3));
		assertEquals(2, PathMechanics.tier(4));
		for (Boss boss : Boss.values())
		{
			assertEquals(PathMechanics.describe(boss, 4), PathMechanics.describe(boss, 6));
		}
	}

	@Test public void scalingContinuesBeyondLastMechanicTier()
	{
		int[] expected = {0, 8, 13, 18, 23, 28, 33};
		for (int i = 0; i < expected.length; i++) assertEquals(expected[i], PathMechanics.statBonusPercent(i));
	}

	@Test(expected = IllegalArgumentException.class) public void missingLevelIsNotSilentlyTreatedAsZero()
	{
		PathMechanics.describe(Boss.AKKHA, -1);
	}

	@Test public void wardensHaveNoInventedPathTier()
	{
		assertEquals(-1, Boss.WARDENS.levelVarbit);
		assertEquals("No separate Warden path level.", PathMechanics.describe(Boss.WARDENS, -1).get(0));
		assertSame(Boss.WARDENS, Boss.forRegion(15184, false));
		assertSame(Boss.WARDENS, Boss.forRegion(15696, false));
	}

	@Test public void puzzleVisibilityIsOptional()
	{
		assertNull(Boss.forRegion(14674, false));
		assertSame(Boss.AKKHA, Boss.forRegion(14674, true));
		assertSame(Boss.AKKHA, Boss.forRegion(14676, false));
		assertTrue(Boss.isRaidRegion(14674));
		assertFalse(Boss.isRaidRegion(13454));
	}
}

package com.cornwall92.toapathwatch;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RegionResolverTest
{
	private Client client;
	private Player player;
	private WorldView worldView;

	@Before public void setUp()
	{
		client = mock(Client.class);
		player = mock(Player.class);
		worldView = mock(WorldView.class);
		when(worldView.getId()).thenReturn(WorldView.TOPLEVEL);
		when(client.getLocalPlayer()).thenReturn(player);
		when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(worldView);
		when(player.getLocalLocation()).thenReturn(at(12, 12));
	}

	private LocalPoint at(int sceneX, int sceneY)
	{
		return new LocalPoint(sceneX * 128 + 64, sceneY * 128 + 64, WorldView.TOPLEVEL);
	}

	private int[][][] instance()
	{
		int[][][] chunks = new int[4][13][13];
		when(worldView.isInstance()).thenReturn(true);
		when(worldView.getInstanceTemplateChunks()).thenReturn(chunks);
		return chunks;
	}

	@Test public void missingPlayerIsUnknown()
	{
		when(client.getLocalPlayer()).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingLocalPointIsUnknown()
	{
		when(player.getLocalLocation()).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingWorldViewIsUnknown()
	{
		when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(null);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void ordinaryWorldUsesPlayersWorldView()
	{
		when(worldView.getBaseX()).thenReturn(52 * 64);
		when(worldView.getBaseY()).thenReturn(142 * 64);
		assertEquals(13454, RegionResolver.region(client));
		verify(client, never()).getTopLevelWorldView();
	}

	@Test public void validInstanceUsesTemplateRegion()
	{
		int[][][] chunks = instance();
		chunks[0][1][1] = (57 * 8 << 14) | (84 * 8 << 3);
		assertEquals(Boss.AKKHA.bossRegion, RegionResolver.region(client));
	}

	@Test public void unloadedChunkIsUnknownInsteadOfSyntheticOutsideRegion()
	{
		int[][][] chunks = instance();
		chunks[0][1][1] = -1;
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingInstanceArrayIsUnknown()
	{
		when(worldView.isInstance()).thenReturn(true);
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void invalidOrUnloadedPlaneIsUnknown()
	{
		int[][][] chunks = instance();
		when(worldView.getPlane()).thenReturn(-1);
		assertEquals(-1, RegionResolver.region(client));
		when(worldView.getPlane()).thenReturn(4);
		assertEquals(-1, RegionResolver.region(client));
		when(worldView.getPlane()).thenReturn(0);
		chunks[0] = null;
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void missingOrShortChunkRowsAreUnknown()
	{
		int[][][] chunks = instance();
		chunks[0][1] = null;
		assertEquals(-1, RegionResolver.region(client));
		chunks[0][1] = new int[1];
		assertEquals(-1, RegionResolver.region(client));
		chunks[0] = new int[1][13];
		assertEquals(-1, RegionResolver.region(client));
	}

	@Test public void sceneCoordinatesOutsideTemplateGridAreUnknown()
	{
		instance();
		when(player.getLocalLocation()).thenReturn(at(-1, 12));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(12, -1));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(104, 12));
		assertEquals(-1, RegionResolver.region(client));
		when(player.getLocalLocation()).thenReturn(at(12, 104));
		assertEquals(-1, RegionResolver.region(client));
	}
}

